<?php
require __DIR__.'/auth.php';requireAdmin();require dirname(__DIR__).'/includes/bootstrap.php';
require dirname(__DIR__).'/Config/catalog.php';
require dirname(__DIR__).'/Config/property-documents.php';
require_once dirname(__DIR__).'/Config/blog.php';
$errors=[];$data=[];$types=catalogNames('property_type');$locations=catalogNames('location');
$fields=['title','city','address','description','type','purpose','price','beds','baths','area','amenities','featured','nearest_locations','subtitle','state','zip','balconies','floors','parking','youtube_videos','youtube_shorts'];foreach($fields as $field)$data[$field]=is_string($_POST[$field]??null)?trim($_POST[$field]):'';
$editSlug=is_string($_GET['slug']??null)?$_GET['slug']:'';$existing=null;
if($editSlug!==''){$q=adminDb()->prepare('SELECT payload FROM properties WHERE slug=?');$q->execute([$editSlug]);$payload=$q->fetchColumn();if(!$payload){http_response_code(404);exit('Property not found.');}$existing=json_decode($payload,true,512,JSON_THROW_ON_ERROR);}
if($existing&&$_SERVER['REQUEST_METHOD']!=='POST'){
 foreach($fields as $field){$value=$existing[$field]??'';$data[$field]=is_scalar($value)?(string)$value:'';}
 $data['featured']=!empty($existing['featured'])?'1':'';
 if(is_array($existing['nearest_locations']??null))$data['nearest_locations']=implode("\n",array_map(fn($place)=>$place['name'].' | '.($place['distance']??''),$existing['nearest_locations']));
 foreach($existing['videos']??[] as $video){if(is_string($video))$video=['url'=>$video,'type'=>'video'];$field=($video['type']??'')==='short'?'youtube_shorts':'youtube_videos';$data[$field].=($data[$field]!==''?"\n":'').$video['url'];}
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 adminCsrf();
 foreach(['title'=>150,'city'=>100,'address'=>300,'description'=>10000,'amenities'=>2000,'nearest_locations'=>4000,'subtitle'=>200,'state'=>100,'zip'=>30,'parking'=>100,'youtube_videos'=>2000,'youtube_shorts'=>2000] as $key=>$max){if(in_array($key,['title','city','description'],true)&&$data[$key]==='')$errors[]=ucfirst($key).' is required.';if(mb_strlen($data[$key])>$max)$errors[]=ucfirst($key).' is too long.';}
 if(!in_array($data['city'],$locations,true))$errors[]='Choose a location from the catalog.';
 if(!in_array($data['type'],$types,true)||!in_array($data['purpose'],['Rent','Sell'],true))$errors[]='Choose a valid type and purpose.';
 foreach(['price'=>100000000000,'area'=>100000000,'beds'=>100,'baths'=>100] as $key=>$max){if(!is_numeric($data[$key])||(float)$data[$key]<0||(float)$data[$key]>$max||($key==='area'&&(float)$data[$key]<=0)|| (in_array($key,['beds','baths'],true)&&floor((float)$data[$key])!=(float)$data[$key]))$errors[]='Enter a valid '. $key.'.';}
 $pricingUploads=[];try{$pricingUploads=propertyDocumentUploads($_FILES['pricing_documents']??[]);}catch(InvalidArgumentException $e){$errors[]=$e->getMessage();}
 if(count(preg_split('/\R/',trim($data['nearest_locations'])))>20)$errors[]='Add up to 20 nearest locations.';
 $galleryUploads=[];try{$galleryUploads=propertyDocumentUploads($_FILES['gallery']??[]);foreach($galleryUploads as $image){if($image['type']!=='image')throw new InvalidArgumentException('Gallery accepts images only.');}}catch(InvalidArgumentException $e){$errors[]='Gallery: '.$e->getMessage();}
 $videos=[];
 if(isset($_POST['video_entries'])){
  $entries=is_string($_POST['video_entries'])?json_decode($_POST['video_entries'],true):null;
  if(!is_array($entries)||!array_is_list($entries)||count($entries)>10)$errors[]='Add up to 10 valid YouTube entries.';
  else foreach($entries as $entry){if(!is_array($entry)||!is_string($entry['url']??null)||!is_string($entry['title']??null)||!in_array($entry['type']??'', ['video','short'],true)){$errors[]='Invalid YouTube entry.';continue;}if(trim($entry['url'])==='')continue;$id=blogYoutubeId(trim($entry['url']));if(!$id||mb_strlen($entry['title'])>150){$errors[]='Enter a valid YouTube link and a title up to 150 characters.';continue;}$videos[]=['url'=>'https://www.youtube.com/watch?v='.$id,'type'=>$entry['type'],'title'=>trim($entry['title'])?:($entry['type']==='short'?'Property short':'Property video')];}
 }else{foreach(['youtube_videos'=>'video','youtube_shorts'=>'short'] as $field=>$videoType){foreach(preg_split('/\R/',$data[$field]) as $url){if(trim($url)==='')continue;$id=blogYoutubeId(trim($url));if(!$id){$errors[]='Enter valid YouTube links.';break;}$videos[]=['url'=>'https://www.youtube.com/watch?v='.$id,'type'=>$videoType,'title'=>$videoType==='short'?'Property short':'Property video'];}}if(count($videos)>10)$errors[]='Add up to 10 YouTube videos.';}

 foreach(['balconies','floors'] as $field){if($data[$field]!==''&&(!ctype_digit($data[$field])||(int)$data[$field]>200))$errors[]='Enter a valid '.$field.'.';}
 $upload=$_FILES['photo']??null;$extension='';
 if((!$upload||$upload['error']===UPLOAD_ERR_NO_FILE)&&$existing){}
 elseif(!$upload||$upload['error']!==UPLOAD_ERR_OK)$errors[]='Upload a cover photo (JPEG, PNG or WebP, max 5 MB).';
 else{ $mime=(new finfo(FILEINFO_MIME_TYPE))->file($upload['tmp_name']);$extension=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';$size=@getimagesize($upload['tmp_name']);if(!$extension||!$size||$upload['size']>5*1024*1024||$size[0]*$size[1]>40000000)$errors[]='Photo must be a valid JPEG, PNG or WebP up to 5 MB and 40 megapixels.'; }
 if(!$errors){
  $record=array_merge($existing??[],$data);$record['slug']=$existing['slug']??(trim(strtolower(preg_replace('/[^a-z0-9]+/i','-',$data['title'])),'-').'-'.bin2hex(random_bytes(4)));
  $record['featured']=$data['featured']==='1';$record['is_sample']=$existing['is_sample']??false;
  foreach(['price','area'] as $key)$record[$key]=(float)$data[$key];foreach(['beds','baths'] as $key)$record[$key]=(int)$data[$key];
  $record['videos']=$videos;unset($record['youtube_videos'],$record['youtube_shorts']);
  $savedFiles=[];
  try{
   if($extension!==''){$filename=bin2hex(random_bytes(16)).'.'.$extension;$target=dirname(__DIR__).'/assets/uploads/'.$filename;if(!move_uploaded_file($upload['tmp_name'],$target))throw new RuntimeException('Cover upload failed.');$savedFiles[]=$target;$record['image']='./assets/uploads/'.$filename;}
   foreach(['gallery'=>$galleryUploads,'pricing_documents'=>$pricingUploads] as $key=>$uploads){
    if($uploads){$record[$key]=[];foreach($uploads as $file){$name=($key==='gallery'?'gallery-':'pricing-').bin2hex(random_bytes(16)).'.'.$file['extension'];$target=dirname(__DIR__).'/assets/uploads/'.$name;if(!move_uploaded_file($file['tmp'],$target))throw new RuntimeException('Upload failed.');$savedFiles[]=$target;$url='./assets/uploads/'.$name;$record[$key][]=$key==='gallery'?$url:['url'=>$url,'name'=>$file['name'],'type'=>$file['type']];}}
    else $record[$key]=$existing[$key]??[];
   }
   if($existing){$statement=adminDb()->prepare('UPDATE properties SET payload=? WHERE slug=?');$statement->execute([json_encode($record,JSON_THROW_ON_ERROR),$editSlug]);}
   else{$statement=adminDb()->prepare('INSERT INTO properties (slug,payload) VALUES (?,?)');$statement->execute([$record['slug'],json_encode($record,JSON_THROW_ON_ERROR)]);}
   if($existing){$old=array_merge([$existing['image']],$existing['gallery']??[],array_column($existing['pricing_documents']??[],'url'));$kept=array_merge([$record['image']],$record['gallery'],array_column($record['pricing_documents'],'url'));foreach(array_diff($old,$kept) as $url){if(!preg_match('~^\./assets/uploads/(?:gallery-|pricing-)?[a-f0-9]{32}\.(?:jpg|png|webp|pdf)$~',$url))continue;try{$probe=adminDb()->prepare('SELECT COUNT(*) FROM properties WHERE payload LIKE ?');$probe->execute(['%'.basename($url).'%']);if(!(int)$probe->fetchColumn())@unlink(dirname(__DIR__).'/'.substr($url,2));}catch(Throwable $cleanupError){error_log('Property upload cleanup could not complete.');}}}
   header('Location: ./properties?'.($existing?'updated':'created').'=1');exit;
  }catch(Throwable $e){foreach($savedFiles as $file)if(is_file($file))unlink($file);$errors[]='Property could not be saved. Please try again.';}
 }

}
require dirname(__DIR__).'/includes/listings.php';
$properties=listingData();$view='properties';$title=$existing?'Edit property':'Create property';
require __DIR__.'/header.php'; ?><div class="page-heading"><div><span class="eyebrow">PROPERTY MANAGEMENT</span><h1><?= $existing?'Edit property':'Create a property' ?></h1><p>Saved properties appear in the admin inventory and public listing page.</p></div></div><?php if($errors): ?><div class="form-error" role="alert"><ul><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?><?php if(!$types||!$locations): ?><div class="form-error">Add property types and locations in <a href="./catalog">Catalog</a> before creating a property.</div><?php endif; ?><form method="post" enctype="multipart/form-data" class="property-form"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><section class="panel form-section"><h2>Property details</h2><div class="form-grid"><?php foreach(['title'=>['Property title','text',150],'address'=>['Street address (optional)','text',300]] as $key=>$field): ?><label><?= e($field[0]) ?><input name="<?= $key ?>" type="<?= $field[1] ?>" maxlength="<?= $field[2] ?>" value="<?= e($data[$key]) ?>" <?= $key!=='address'?'required':'' ?>></label><?php endforeach; ?><label>Location<select name="city" required><option value="">Choose location</option><?php foreach($locations as $location): ?><option <?= $data['city']===$location?'selected':'' ?>><?= e($location) ?></option><?php endforeach; ?></select></label><label>Property type<select name="type" required><option value="">Choose type</option><?php foreach($types as $type): ?><option <?= $data['type']===$type?'selected':'' ?>><?= e($type) ?></option><?php endforeach; ?></select></label><label>Purpose<select name="purpose" required><option value="">Choose purpose</option><?php foreach(['Rent','Sell'] as $purpose): ?><option <?= $data['purpose']===$purpose?'selected':'' ?>><?= $purpose ?></option><?php endforeach; ?></select></label><label>Price (PKR; monthly for rent)<input type="number" name="price" min="0" max="100000000000" step="0.01" value="<?= e($data['price']) ?>" required></label><?php foreach(['beds'=>'Bedrooms','baths'=>'Bathrooms','area'=>'Area (sq.ft)'] as $key=>$label): ?><label><?= e($label) ?><input type="number" name="<?= $key ?>" min="<?= $key==='area'?'0.01':'0' ?>" max="<?= $key==='area'?'100000000':'100' ?>" step="<?= $key==='area'?'0.01':'1' ?>" value="<?= e($data[$key]) ?>" required></label><?php endforeach; ?><?php foreach(['subtitle'=>'Short description','state'=>'State / province','zip'=>'Postal code','balconies'=>'Balconies','floors'=>'Total floors','parking'=>'Parking'] as $key=>$label): ?><label><?= e($label) ?><input name="<?= $key ?>" value="<?= e($data[$key]) ?>" maxlength="<?= $key==='zip'?30:($key==='subtitle'?200:100) ?>" <?= in_array($key,['balconies','floors'],true)?'type="number" min="0" max="200"':'' ?>></label><?php endforeach; ?></div><label>Description<textarea name="description" rows="5" maxlength="10000" required><?= e($data['description']) ?></textarea></label><label>Amenities<textarea name="amenities" rows="3" maxlength="2000" placeholder="Parking&#10;Security&#10;Balcony"><?= e($data['amenities']) ?></textarea></label><label class="checkbox-label"><input type="checkbox" name="featured" value="1" <?= $data['featured']==='1'?'checked':'' ?>> Feature this property</label></section><section class="panel form-section"><h2>Cover photo</h2><p>JPEG, PNG or WebP, up to 5 MB. Re-select your photo if the form reports an error.</p><label>Upload photo<input id="property-photo" type="file" name="photo" accept="image/jpeg,image/png,image/webp" <?= $existing?'':'required' ?>></label><img id="photo-preview" alt="Property cover preview" <?= $existing?'src="../'.e(substr($existing['image'],2)).'"':'hidden' ?>></section><section class="panel form-section"><h2>Gallery</h2><?php if($existing): ?><p>Existing images remain unless you upload a replacement gallery.</p><div class="property-upload-previews"><?php foreach($existing['gallery']??[] as $photo): ?><img src="../<?= e(substr($photo,2)) ?>" alt="Saved gallery photo"><?php endforeach; ?></div><?php endif; ?><p>Up to 5 additional JPEG, PNG or WebP images, up to 10 MB each. The cover photo is shown first.</p><label>Upload gallery images<input id="property-gallery" name="gallery[]" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><div id="property-gallery-preview" class="property-upload-previews"></div></section><section class="panel form-section"><h2>YouTube videos</h2><input type="hidden" name="video_entries" id="property-video-entries" disabled value="<?= e(json_encode(is_string($_POST['video_entries']??null)?(json_decode($_POST['video_entries'],true)??[]):($existing['videos']??[]),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)) ?>"><div class="form-grid"><label>Videos<textarea name="youtube_videos" rows="4" maxlength="2000" placeholder="https://www.youtube.com/watch?v=..."><?= e($data['youtube_videos']) ?></textarea></label><label>Shorts<textarea name="youtube_shorts" rows="4" maxlength="2000" placeholder="https://www.youtube.com/shorts/..."><?= e($data['youtube_shorts']) ?></textarea></label></div><p>Up to 10 videos or Shorts. YouTube links appear as playable videos on the detail page.</p></section><section class="panel form-section"><h2>Pricing Documents</h2><?php if($existing): ?><p>Existing documents remain unless you upload replacements.</p><?php foreach($existing['pricing_documents']??[] as $document): ?><p><a href="../<?= e(substr($document['url'],2)) ?>" target="_blank" rel="noopener"><?= e($document['name']) ?></a></p><?php endforeach; ?><?php endif; ?><p>Optional: upload up to 5 PDF or image documents, up to 10 MB each. Re-select files if validation fails.</p><label>Upload pricing documents<input type="file" name="pricing_documents[]" multiple accept="application/pdf,image/jpeg,image/png,image/webp"></label></section><section class="panel form-section"><h2>Nearest Locations</h2><p>Add nearby places with their distance or travel time. Up to 20 places.</p><label>Nearby places<textarea name="nearest_locations" rows="5" maxlength="4000" placeholder="School | 1 km&#10;Hospital | 5 minutes&#10;Shopping mall | 2 km"><?= e($data['nearest_locations']) ?></textarea></label></section><div class="form-actions"><a href="./properties">Cancel</a><button class="primary-button" type="submit"><?= $existing?'Save changes':'Create property' ?></button></div></form><?php require __DIR__.'/footer.php'; ?>
